contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount, address other) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);
        require(other != address(this));

        uint256 beforeOtherBal = c.balances(other); if (__ESBMC_reverted()) return;
        uint256 beforeCallerBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeDeposited = beforeCallerBal + beforeOtherBal;

        c.Deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint256 afterOtherBal = c.balances(other); if (__ESBMC_reverted()) return;
        uint256 afterCallerBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterContractBalance = address(c).balance;

        assert(afterCallerBal == beforeCallerBal + amount && afterOtherBal == beforeOtherBal && afterContractBalance == beforeContractBalance + amount);
    }

    receive() external payable {}
}

