pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 amount, address other) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(address(this).balance >= amount);
        vm.assume(other != address(this));
        uint256 beforeOtherBal;
        try c.balances(other) returns (uint256 __r) { beforeOtherBal = __r; } catch { return; }
        uint256 beforeCallerBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeCallerBal = __r; } catch { return; }
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeDeposited = beforeCallerBal + beforeOtherBal;
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 afterOtherBal;
        try c.balances(other) returns (uint256 __r) { afterOtherBal = __r; } catch { return; }
        uint256 afterCallerBal;
        try c.balances(address(this)) returns (uint256 __r) { afterCallerBal = __r; } catch { return; }
        uint256 afterContractBalance = address(c).balance;
        assertTrue(afterCallerBal == beforeCallerBal + amount && afterOtherBal == beforeOtherBal && afterContractBalance == beforeContractBalance + amount);
    }

    function testFuzz_run(uint256 amount, address other) public {
        vm.assume(other.code.length == 0 && uint160(other) > 0xffff && other != address(this) && other != address(c) && other != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && other != 0x000000000000000000636F6e736F6c652e6c6f67 && other != 0x4e59b44847b379578588920cA78FbF26c0B4956C && other != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(amount, other);
    }

    receive() external payable {}
}
